import{_ as e,o as a,a as r,a2 as o}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"product-type-development/getting-started.md","filePath":"product-type-development/getting-started.md","lastUpdated":1790143103000}'),i={name:"product-type-development/getting-started.md"};function d(s,t,n,c,p,h){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>A product type in Bagisto decides how a product behaves: whether it ships, how its stock and price are checked, and what goes into the cart. This section registers a custom type from a package, explains the class behind it, then turns it into a subscription a customer can buy, without editing a core package.</p><h2 id="what-you-ll-build" tabindex="-1">What You&#39;ll Build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What You&#39;ll Build&quot;">​</a></h2><p><strong><code>Webkul\\SubscriptionProduct</code></strong>, a package that adds the product type <code>subscription</code>:</p><ul><li><strong>Subscription</strong> in the admin&#39;s product type list, backed by its own class</li><li>no shipping step at checkout for a cart of subscriptions</li><li>a weekly, monthly or yearly frequency the customer picks on the product page, kept on the cart item and the order item</li></ul><p>The type records the frequency the customer chose; it doesn&#39;t bill renewals.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Paths are relative to <code>packages/Webkul/SubscriptionProduct/src</code>.</p><table tabindex="0"><thead><tr><th>Part</th><th>File</th><th>Plugs into</th></tr></thead><tbody><tr><td>Product type configuration</td><td><code>Config/product_types.php</code></td><td>Merged into <code>config(&#39;product_types&#39;)</code>; the admin&#39;s type list reads it, and <code>Product::getTypeInstance()</code> resolves its <code>class</code></td></tr><tr><td>Product type class</td><td><code>Type/Subscription.php</code></td><td>Extends <code>Webkul\\Product\\Type\\AbstractType</code>; decides shipping, stock, the cart rows and the price indexer</td></tr><tr><td>Translations</td><td><code>Resources/lang/en/app.php</code></td><td>The <code>subscription::</code> namespace: the type&#39;s name and the storefront labels</td></tr><tr><td>Product page field</td><td><code>Resources/views/shop/products/frequency.blade.php</code></td><td>The <code>bagisto.shop.products.short_description.after</code> view render event</td></tr><tr><td>Service provider</td><td><code>Providers/SubscriptionServiceProvider.php</code></td><td>Merges the configuration and loads the translations, views and listener; listed in <code>bootstrap/providers.php</code></td></tr></tbody></table><p>Unlike a shipping or payment method, a product type has no section in the admin configuration. A product&#39;s data stays in the attributes of its attribute family; the type class decides what Bagisto does with it.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Bagisto 2.5, installed and running: see <a href="./../getting-started/installation.html">Installation</a>.</li><li>How a package is autoloaded and its provider registered: see <a href="./../package-development/getting-started.html">Package Development</a>.</li></ul><h2 id="the-path" tabindex="-1">The Path <a class="header-anchor" href="#the-path" aria-label="Permalink to &quot;The Path&quot;">​</a></h2><ol><li><a href="./create-your-first-product-type.html">Creating Your First Product Type</a>: register the type and create a product of it in the admin.</li><li><a href="./understanding-product-type-configuration.html">Understanding Product Type Configuration</a>: the <code>product_types.php</code> keys, core&#39;s seven types, and overriding one.</li><li><a href="./understanding-abstract-type-class.html">Understanding the AbstractType Class</a>: the properties and methods a type overrides.</li><li><a href="./building-your-subscription-product-type.html">Building Your Subscription Product Type</a>: the frequency field, the cart rows and a checkout without shipping.</li></ol><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Start by registering the type.</p><p><strong>Continue to:</strong> <a href="./create-your-first-product-type.html">Creating Your First Product Type</a></p>',17)]))}const g=e(i,[["render",d]]);export{u as __pageData,g as default};
